   100	static int mem_new(BIO *bio) {
   101	  BUF_MEM *b;
   102	
   103	  b = BUF_MEM_new();
   104	  if (b == NULL) {
   105	    return 0;
   106	  }
   107	
   108	  // |shutdown| is used to store the close flag: whether the BIO has ownership
   109	  // of the BUF_MEM.
   110	  bio->shutdown = 1;
   111	  bio->init = 1;
   112	  bio->num = -1;
   113	  bio->ptr = (char *)b;
   114	
   115	  return 1;
   116	}
   117	
   118	static int mem_free(BIO *bio) {
   119	  BUF_MEM *b;
   120	
   121	  if (bio == NULL) {
   122	    return 0;
   123	  }
   124	
   125	  if (!bio->shutdown || !bio->init || bio->ptr == NULL) {
   126	    return 1;
   127	  }
   128	
   129	  b = (BUF_MEM *)bio->ptr;
   130	  if (bio->flags & BIO_FLAGS_MEM_RDONLY) {
   131	    b->data = NULL;
   132	  }
   133	  BUF_MEM_free(b);
   134	  bio->ptr = NULL;
   135	  return 1;
   136	}
