   192	static int mem_gets(BIO *bio, char *buf, int size) {
   193	  int i, j;
   194	  char *p;
   195	  BUF_MEM *b = (BUF_MEM *)bio->ptr;
   196	
   197	  BIO_clear_retry_flags(bio);
   198	  j = b->length;
   199	  if (size - 1 < j) {
   200	    j = size - 1;
   201	  }
   202	  if (j <= 0) {
   203	    if (size > 0) {
   204	      *buf = 0;
   205	    }
   206	    return 0;
   207	  }
   208	
   209	  p = b->data;
   210	  for (i = 0; i < j; i++) {
   211	    if (p[i] == '\n') {
   212	      i++;
   213	      break;
   214	    }
   215	  }
   216	
   217	  // i is now the max num of bytes to copy, either j or up to and including the
   218	  // first newline
   219	
   220	  i = mem_read(bio, buf, i);
   221	  if (i > 0) {
   222	    buf[i] = '\0';
   223	  }
   224	  return i;
   225	}
