   303	int BIO_mem_contents(const BIO *bio, const uint8_t **out_contents,
   304	                     size_t *out_len) {
   305	  const BUF_MEM *b;
   306	  if (bio->method != &mem_method) {
   307	    return 0;
   308	  }
   309	
   310	  b = (BUF_MEM *)bio->ptr;
   311	  *out_contents = (uint8_t *)b->data;
   312	  *out_len = b->length;
   313	  return 1;
   314	}
